mapper.select:
SELECT 
  FROM course c
 WHERE c.course_id = #{courseId}

mapper.update:
UPDATE course
   SET is_active  = FALSE,
       deleted_at = #{deletedAt},
       updated_at = #{deletedAt}
 WHERE course_id  = #{courseId}
   AND is_active  = TRUE

UPDATE course
   SET is_active  = TRUE,
       deleted_at = NULL,
       updated_at = #{updatedAt}
 WHERE course_id  = #{courseId}
   AND is_active  = FALSE
